#!/usr/bin/env bash
# Claude Code status line (see claude/settings.json → statusLine)
# Reads session JSON on stdin; prints dir, git branch/status, model, context, tokens, cost, CPU, memory, battery.

input=$(cat); cwd=$(echo "$input" | jq -r '.workspace.current_dir'); short_dir=$(echo "$cwd" | sed "s|^$HOME|~|"); branch=$(git -C "$cwd" --no-optional-locks branch --show-current 2>/dev/null || echo ""); git_status=$(git -C "$cwd" --no-optional-locks status --porcelain 2>/dev/null); model=$(echo "$input" | jq -r '.model.display_name'); model_id=$(echo "$input" | jq -r '.model.id'); used_pct=$(echo "$input" | jq -r '.context_window.used_percentage // empty'); total_input=$(echo "$input" | jq -r '.context_window.total_input_tokens // 0'); total_output=$(echo "$input" | jq -r '.context_window.total_output_tokens // 0'); context_size=$(echo "$input" | jq -r '.context_window.context_window_size // 0'); transcript_path=$(echo "$input" | jq -r '.transcript_path'); printf "\033[36m%s\033[0m" "$short_dir"; if [ -n "$branch" ]; then if [ -z "$git_status" ]; then printf " \033[32m%s\033[0m" "$branch"; else printf " \033[33m%s\033[0m" "$branch"; indicators=""; echo "$git_status" | grep -q "^??" && indicators="${indicators}?"; echo "$git_status" | grep -q "^[MARCD]" && indicators="${indicators}+"; echo "$git_status" | grep -q "^.[MD]" && indicators="${indicators}!"; [ -n "$indicators" ] && printf " \033[33m%s\033[0m" "$indicators"; fi; fi; if [ -n "$used_pct" ] && [ "$context_size" -gt 0 ]; then used_tokens=$(echo "$used_pct * $context_size / 100" | bc | cut -d. -f1); used_k=$((used_tokens / 1000)); context_k=$((context_size / 1000)); used_int=$(printf "%.1f" "$used_pct"); remaining_pct=$(echo "100 - $used_pct" | bc); remaining_int=$(printf "%.0f" "$remaining_pct"); input_k=$((total_input / 1000)); output_k=$((total_output / 1000)); if [ -f "$transcript_path" ]; then msg_count=$(grep -c '"role":' "$transcript_path" 2>/dev/null || echo 0); msg_count=$((msg_count / 2)); birth_time=$(stat -f %B "$transcript_path" 2>/dev/null || stat -c %W "$transcript_path" 2>/dev/null || echo 0); current_time=$(date +%s); duration=$((current_time - birth_time)); hours=$((duration / 3600)); minutes=$(((duration % 3600) / 60)); seconds=$((duration % 60)); if [ $hours -gt 0 ]; then duration_str=$(printf "%dh %dm" $hours $minutes); elif [ $minutes -gt 0 ]; then duration_str=$(printf "%dm %ds" $minutes $seconds); else duration_str=$(printf "%ds" $seconds); fi; else msg_count=0; duration_str="--"; fi; case "$model_id" in *opus*) input_price=15; output_price=75 ;; *sonnet*) input_price=3; output_price=15 ;; *haiku*) input_price=0.25; output_price=1.25 ;; *) input_price=3; output_price=15 ;; esac; cost=$(echo "scale=4; ($total_input / 1000000 * $input_price) + ($total_output / 1000000 * $output_price)" | bc); cost_display=$(printf "\$%.4f" $cost); cpu_usage=$(top -l 1 | grep "CPU usage" | awk '{print $3}' | sed 's/%//'); total_ram_gb=$(sysctl -n hw.memsize | awk '{printf "%.0f", $1/1073741824}'); mem_used=$(vm_stat | awk -v tgb="$total_ram_gb" '/Pages active/ {a=$3} /Pages wired/ {w=$4} /Pages occupied by compressor/ {c=$6} END {gsub(/\./,"",a); gsub(/\./,"",w); gsub(/\./,"",c); printf "%.0fG/%dG", (a+w+c)*4096/1073741824, tgb}'); batt_info=$(pmset -g batt | grep -Eo "[0-9]+%" | head -1); batt_charging=$(pmset -g batt | grep -q "charging" && echo " ⚡" || echo ""); batt_display="${batt_info}${batt_charging}"; if [ "$remaining_int" -lt 20 ]; then printf "\n🧠 \033[35m%s\033[0m | 📊 \033[31m%s%% (%dk/%dk)\033[0m | 📨 \033[36m%d msgs\033[0m | 🔄 \033[32m↑%dk\033[0m \033[33m↓%dk\033[0m | ⏱ \033[36m%s\033[0m | 💰 \033[33m%s\033[0m\n💻 \033[32m%s%%\033[0m | 🧠 \033[35m%s\033[0m | 🔋 \033[33m%s\033[0m" "$model" "$used_int" "$used_k" "$context_k" "$msg_count" "$input_k" "$output_k" "$duration_str" "$cost_display" "$cpu_usage" "$mem_used" "$batt_display"; elif [ "$remaining_int" -lt 50 ]; then printf "\n🧠 \033[35m%s\033[0m | 📊 \033[33m%s%% (%dk/%dk)\033[0m | 📨 \033[36m%d msgs\033[0m | 🔄 \033[32m↑%dk\033[0m \033[33m↓%dk\033[0m | ⏱ \033[36m%s\033[0m | 💰 \033[33m%s\033[0m\n💻 \033[32m%s%%\033[0m | 🧠 \033[35m%s\033[0m | 🔋 \033[33m%s\033[0m" "$model" "$used_int" "$used_k" "$context_k" "$msg_count" "$input_k" "$output_k" "$duration_str" "$cost_display" "$cpu_usage" "$mem_used" "$batt_display"; else printf "\n🧠 \033[35m%s\033[0m | 📊 \033[32m%s%% (%dk/%dk)\033[0m | 📨 \033[36m%d msgs\033[0m | 🔄 \033[32m↑%dk\033[0m \033[33m↓%dk\033[0m | ⏱ \033[36m%s\033[0m | 💰 \033[33m%s\033[0m\n💻 \033[32m%s%%\033[0m | 🧠 \033[35m%s\033[0m | 🔋 \033[33m%s\033[0m" "$model" "$used_int" "$used_k" "$context_k" "$msg_count" "$input_k" "$output_k" "$duration_str" "$cost_display" "$cpu_usage" "$mem_used" "$batt_display"; fi; fi
